  h.querySelectorAll('[data-fost-bild]').forEach(e=>e.onchange=()=>{const n=+e.dataset.fostBild,anderer=f.bilder.findIndex((b,i)=>i!==n&&b.fotoId===e.value);if(anderer>=0){[f.bilder[n],f.bilder[anderer]]=[f.bilder[anderer],f.bilder[n]];}else{const b=f.bilder[n];b.fotoId=e.value;b.crop={x:.5,y:.5,zoom:1,modus:'ganz'};}fostAendern(false);fostSerie();});
  h.querySelectorAll('[data-fost-crop]').forEach(e=>e.oninput=()=>{const b=f.bilder[+e.dataset.fostNummer];if(e.dataset.fostCrop==='modus'){b.crop.modus=e.checked?'ganz':'fuellen';fostAendern(false);fostSerie();}else{b.crop[e.dataset.fostCrop]=Number(e.value)/(e.dataset.fostCrop==='zoom'?1:100);const o=e.parentNode.querySelector('output');if(o)o.value=e.dataset.fostCrop==='zoom'?Number(e.value).toFixed(1)+'×':e.value+'%';fostAendern();}});
  fostMiniaturen(h.querySelector('.fost-film'));fostZeichnen();
