function fostFolieAnlegen(){
  const d=FOST.d,liste=d[FOST.format];if(FOST.busy || liste.length>=20)return;
  const verwendet=new Set(liste.flatMap(s=>s.bilder.map(b=>b.fotoId))),p=d.fotos.find(p=>!p.ausgeschlossen&&!verwendet.has(p.id))||d.fotos.find(p=>!p.ausgeschlossen);if(!p)return;
  liste.push({id:crypto.randomUUID(),art:'foto',bilder:[{fotoId:p.id,crop:{x:.5,y:.5,zoom:1,modus:'ganz'}}],titel:'',text:'',alt:''});
  if(FOST.format==='story')d.texte.story.push('');FOST.index=liste.length-1;fostAendern(false);fostSerie();
}

