const SVTH={k:'svbc_theme',mq:null};
function svThWahl(){ try{ const v=localStorage.getItem(SVTH.k); return v==='hell'||v==='dunkel'||v==='system'?v:'system'; }catch(e){ return 'system'; } }   // 0.74: Standard folgt dem Gerät
function svThAktiv(w){ w=w||svThWahl(); if(w==='system'){ try{ return matchMedia('(prefers-color-scheme: light)').matches?'hell':'dunkel'; }catch(e){ return 'dunkel'; } } return w; }
function svThAnwenden(){
  const t=svThAktiv(); document.documentElement.dataset.theme=t;
  try{ let m=document.querySelector('meta[name="theme-color"]'); if(!m){ m=document.createElement('meta'); m.name='theme-color'; document.head.appendChild(m); } m.content=t==='hell'?'#f3eee4':'#05070c'; }catch(e){}
  try{ document.dispatchEvent(new CustomEvent('svthema',{detail:t})); }catch(e){}
}
function svThSetzen(w){ try{ localStorage.setItem(SVTH.k,w); }catch(e){} svThAnwenden(); }
(function(){ svThAnwenden();
  try{ SVTH.mq=matchMedia('(prefers-color-scheme: light)'); const f=()=>{ if(svThWahl()==='system')svThAnwenden(); };
    if(SVTH.mq.addEventListener)SVTH.mq.addEventListener('change',f); else if(SVTH.mq.addListener)SVTH.mq.addListener(f); }catch(e){}
  // auch in anderen offenen Tabs sofort umschalten
  try{ addEventListener('storage',e=>{ if(e.key===SVTH.k)svThAnwenden(); }); }catch(e){}
})();
