function svThKontrast(c){ const a=svThLum(c),b=svThLum(SVTH_P); return (Math.max(a,b)+.05)/(Math.min(a,b)+.05); }
function svThHsl(c){ const r=c.r/255,g=c.g/255,b=c.b/255,mx=Math.max(r,g,b),mn=Math.min(r,g,b); let h=0,s=0; const l=(mx+mn)/2;
  if(mx!==mn){ const d=mx-mn; s=l>.5?d/(2-mx-mn):d/(mx+mn); h=mx===r?(g-b)/d+(g<b?6:0):mx===g?(b-r)/d+2:(r-g)/d+4; h/=6; } return {h,s,l}; }
