(function(){ try{ const s=document.createElement('style'); s.id='svm74css'; s.textContent="/* Beta 0.74 · Ruhige Oberfläche. Liegt als letzte Schicht über design.css und ersetzt den Verlaufs-Look aus 0.39.\n   Prinzip: flache Flächen, eine Kante, eine Akzentfarbe. Kein Verlauf auf Text und Knöpfen, kein Leuchten, keine Deko hinter dem Inhalt.\n   Dunkle Regeln stehen unter html:not([data-theme=\"hell\"]), helle unter html[data-theme=\"hell\"] body (wie in svm53.css),\n   damit hellcss.py sie nicht übersetzt und svhell.css sie nicht überschreibt. */\n:root{\n  --grad-brand:var(--brand);\n  --grad-brand-soft:var(--brandSoft);\n  --grad-gold:var(--gold);\n  --grad-surface:var(--surface);\n  --grad-surface-2:var(--surface2);\n  --kante:transparent;\n  --glow:transparent; --glow-2:none;\n  --r-xl:16px; --r-lg:14px; --r-md:11px; --r-sm:9px;\n}\n/* Hintergrund: eine Farbe */\nhtml:not([data-theme=\"hell\"]) body,html:not([data-theme=\"hell\"]) body:not(#_){background:var(--bg)!important;background-image:none!important;}\nhtml[data-theme=\"hell\"] body,html[data-theme=\"hell\"] body:not(#_){background:var(--bg)!important;background-image:none!important;}\n#svWelt{display:none!important;}\n.hello h2::after{display:none!important;}\n\n/* Karten: flach, eine Kante, kaum Schatten, kein Glas */\nhtml:not([data-theme=\"hell\"]) .card,html:not([data-theme=\"hell\"]) .chartcard,html:not([data-theme=\"hell\"]) .pbcard,html:not([data-theme=\"hell\"]) .fcard,html:not([data-theme=\"hell\"]) .tile{\n  background:var(--surface)!important;border:1px solid var(--line)!important;box-shadow:0 1px 2px rgba(0,0,0,.25)!important;}\nhtml[data-theme=\"hell\"] body .card,html[data-theme=\"hell\"] body .chartcard,html[data-theme=\"hell\"] body .pbcard,html[data-theme=\"hell\"] body .fcard,html[data-theme=\"hell\"] body .tile{\n  background:var(--surface)!important;border:1px solid var(--line)!important;box-shadow:0 1px 2px rgba(60,45,20,.06)!important;}\n.card,.chartcard,.pbcard{backdrop-filter:none!important;-webkit-backdrop-filter:none!important;}\n.card::before,.chartcard::before,.pbcard::before,.sheet::before{display:none!important;}\n.card{border-radius:16px!important;}\n@media (max-width:760px){ .card{border-radius:14px!important;} }\nhtml:not([data-theme=\"hell\"]) .card.svcock{background:var(--surface2)!important;border-color:var(--line)!important;box-shadow:none!important;}\nhtml[data-theme=\"hell\"] body .card.svcock{background:var(--surface2)!important;border-color:var(--line)!important;box-shadow:none!important;}\n.card.svcock .svc-h h3{background:none!important;-webkit-background-clip:unset!important;background-clip:unset!important;color:var(--ink)!important;}\n.svc-a{background:var(--surface2)!important;border:1px solid var(--line)!important;box-shadow:none!important;}\n.svc-a svg{width:22px!important;height:22px!important;padding:0!important;border-radius:0!important;background:none!important;color:var(--brand2)!important;box-shadow:none!important;}\nhtml[data-theme=\"hell\"] body .svc-a svg{color:var(--brand)!important;}\n\n/* Text: kein Verlauf, keine durchsichtige Schrift */\n.hello h2 span,html:not([data-theme=\"hell\"]) .hello h2 span,html[data-theme=\"hell\"] body .hello h2 span,\n.kpi,.stat,.tile b,.spt-kopf h2 span,.g-copy h1 span{\n  background:none!important;-webkit-background-clip:unset!important;background-clip:unset!important;color:var(--ink)!important;-webkit-text-fill-color:currentColor;}\n.hello h2 span{color:var(--brand2)!important;}\nhtml[data-theme=\"hell\"] body .hello h2 span{color:var(--brand)!important;}\n\n/* Rollen-Chip und Avatar: eine Farbe */\n.rolechip.r-admin,.rolechip.r-vorstand,.rolechip.r-trainer,.rolechip.r-planer{background:var(--brandSoft)!important;border-color:var(--line)!important;box-shadow:none!important;}\n.uav,.uav.r-admin{background:var(--brand)!important;color:#fff!important;box-shadow:none!important;border:0!important;}\n\n/* Kopfleiste: deckend, Haarlinie unten */\nhtml:not([data-theme=\"hell\"]) .topbar{background:var(--bg)!important;border-bottom:1px solid var(--line)!important;}\nhtml[data-theme=\"hell\"] body .topbar{background:var(--bg)!important;border-bottom:1px solid var(--line)!important;}\n.topbar{backdrop-filter:none!important;-webkit-backdrop-filter:none!important;}\n.topbar::after{display:none!important;}\n.tb-icon{width:44px!important;height:44px!important;border-radius:12px!important;}\n.tb-me{min-width:44px;min-height:44px;display:none;place-items:center;}\n@media (max-width:760px){ .tb-me{display:grid;} }\n.tb-crest{filter:none!important;}\n\n/* Knöpfe: Vereinsblau, flach. Dunkler als bisher, damit weiße Schrift 4,5:1 erreicht */\nhtml:not([data-theme=\"hell\"]){--brand:#2a5fe6;}\n.btn{background:var(--brand)!important;border:1px solid transparent!important;box-shadow:none!important;color:#fff!important;}\n.btn:hover{filter:brightness(1.08);}\nhtml:not([data-theme=\"hell\"]) .btn.ghost{background:var(--surface2)!important;border:1px solid var(--line)!important;box-shadow:none!important;color:var(--ink)!important;}\nhtml[data-theme=\"hell\"] body .btn.ghost{background:var(--surface2)!important;border:1px solid var(--line)!important;box-shadow:none!important;color:var(--ink)!important;}\n.btn.ghost:hover{border-color:var(--brand2)!important;filter:none;}\n.btn.sm{min-height:36px!important;}\n.rm-ic,.rm-ic.co{background:var(--brandSoft)!important;color:var(--brand2)!important;border:1px solid var(--line)!important;box-shadow:none!important;}\nhtml[data-theme=\"hell\"] body .rm-ic,html[data-theme=\"hell\"] body .rm-ic.co{color:var(--brand)!important;}\n\n/* Untere Leiste: angedockt, deckend, Haarlinie oben, Mindesthöhe 48 je Reiter. body:not(#_) schlägt die älteren Schichten (svm53) */\n@media (max-width:760px){\n  html body:not(#_) .tabbar{left:0!important;right:0!important;bottom:0!important;border-radius:0!important;padding:6px 4px calc(6px + env(safe-area-inset-bottom))!important;\n    border:0!important;border-top:1px solid var(--line)!important;box-shadow:none!important;backdrop-filter:none!important;-webkit-backdrop-filter:none!important;background:var(--surface)!important;}\n  html body:not(#_) .tabbar .ti,html body:not(#_) .tabbar .tmore{border-radius:10px!important;min-height:48px;padding:6px 2px 4px!important;font-size:11px!important;background:none!important;box-shadow:none!important;}\n  html body:not(#_) .tabbar .ti.active{color:var(--brand2)!important;}\n  html[data-theme=\"hell\"] body:not(#_) .tabbar .ti.active{color:var(--brand)!important;}\n  html body:not(#_) .tabbar .ti.active svg{color:currentColor!important;}\n  html body:not(#_) .tabbar .ti.active::after{display:none!important;}\n  html body:not(#_) main{padding-bottom:calc(84px + env(safe-area-inset-bottom))!important;}\n}\n\n/* Listen und Leisten: flach */\nhtml:not([data-theme=\"hell\"]) .kal-it,html:not([data-theme=\"hell\"]) .og-p,html:not([data-theme=\"hell\"]) .og-karte,html:not([data-theme=\"hell\"]) .row{background:var(--surface2)!important;border:1px solid var(--line)!important;box-shadow:none!important;}\nhtml[data-theme=\"hell\"] body .kal-it,html[data-theme=\"hell\"] body .og-p,html[data-theme=\"hell\"] body .og-karte,html[data-theme=\"hell\"] body .row{background:var(--surface2)!important;border:1px solid var(--line)!important;box-shadow:none!important;}\n.kal-bar{background:var(--c,var(--brand2))!important;box-shadow:none!important;}\n.card h3.trh::before,.kal-hh h3::before{background:var(--brand2)!important;}\n.svc-ins .note{background:var(--surface2)!important;border:1px solid var(--line)!important;}\n.online .lbl,.gsearch input,.fbar,.og-filter{background:var(--surface2)!important;border:1px solid var(--line)!important;box-shadow:none!important;}\n.og-filter button.on,.fbar .on{background:var(--brand)!important;color:#fff!important;box-shadow:none!important;}\n.og-ring .fg{stroke:var(--brand2);}\n\n/* Blätter und Dialoge: flach */\nhtml:not([data-theme=\"hell\"]) .sheet{background:var(--surface)!important;border-top:1px solid var(--line)!important;box-shadow:0 -8px 30px rgba(0,0,0,.4)!important;border-radius:18px 18px 0 0!important;}\nhtml[data-theme=\"hell\"] body .sheet{background:var(--surface)!important;border-top:1px solid var(--line)!important;box-shadow:0 -8px 30px rgba(60,45,20,.12)!important;border-radius:18px 18px 0 0!important;}\n.sheet h4::before{display:none!important;}\n.sheet h4{margin:12px 4px 6px!important;font-size:11.5px!important;letter-spacing:.06em;text-transform:uppercase;color:var(--ink3)!important;}\n.sgrid button{border-radius:12px!important;}\n.w5-gruss{display:none!important;}\n\n\n/* Keine Leuchtschatten mehr, egal wo */\n.g-orb,.g-art::before,.g-art::after{display:none!important;}\n.spt-mic,.spt-av,.spt-home-mic,.spt-iv-mic{background:var(--brand)!important;box-shadow:none!important;border:0!important;}\n\n/* Erklärkästen: flach, eine Zeile wenn zu */\n.info50{background:var(--surface2)!important;border:1px solid var(--line)!important;border-radius:12px!important;}\n.info50-h{color:var(--ink2)!important;}\n\n/* Suche am Handy: eigener, deckender Bildschirm statt durchsichtiger Ebene über der Seite */\n@media (max-width:760px){\n  .gsearch.mopen{position:fixed!important;inset:0!important;width:auto!important;z-index:80!important;display:flex!important;flex-direction:column;\n    padding:calc(12px + env(safe-area-inset-top)) 14px calc(12px + env(safe-area-inset-bottom));background:var(--bg)!important;}\n  .gsearch.mopen::before{display:none!important;}\n  .gsearch.mopen>svg{left:28px!important;top:calc(12px + env(safe-area-inset-top) + 25px)!important;}\n  .gsearch.mopen input{background:var(--surface2)!important;box-shadow:none!important;min-height:50px;padding-left:42px!important;}\n  .gsearch.mopen .gres{display:block!important;position:static!important;flex:1;max-height:none!important;margin-top:10px;padding:0!important;\n    background:transparent!important;border:0!important;box-shadow:none!important;overflow:auto;}\n  .gsearch.mopen .gres>*{min-width:0;}\n}\n.su-ber .su-ber-ic{width:36px;height:36px;border-radius:10px;display:grid;place-items:center;background:var(--brandSoft);color:var(--brand2);flex:none;}\n.su-ber .su-ber-ic svg{width:18px;height:18px;}\n\n/* „Nur du bist gerade online“: Anwesenheit nur zeigen, wenn wirklich jemand da ist (svm41.js setzt .allein) */\n.online.allein,.online-chip.allein{display:none!important;}\n\n/* Kopfzeile am Handy: drei Knöpfe rechts, der Titel darf kleiner werden statt abgeschnitten */\n@media (max-width:760px){\n  #pgTitle{font-size:clamp(17px,5.2vw,21px)!important;letter-spacing:-.02em;}\n  /* Wie bei Apple: am Handy Titel statt Wappen in der Kopfzeile, damit „Mannschaftskasse“ oder „Spieltagsstudio“ ganz passt */\n  html body:not(#_) .topbar .tb-crest{display:none!important;}\n  html body:not(#_) .topbar{gap:8px!important;}\n  body:has(.gsearch.mopen) .tabbar{display:none!important;}\n}\n\n/* Offline-Hinweis oben, deckend, ruhig */\n#sv68off{position:fixed;left:0;right:0;top:0;z-index:90;padding:calc(8px + env(safe-area-inset-top)) 16px 8px;background:#3a2a06;color:#fde68a;font-size:13.5px;line-height:1.4;\n  transform:translateY(-100%);transition:transform .25s var(--ease);border-bottom:1px solid rgba(251,191,36,.3);}\n#sv68off.an{transform:none;}\nhtml[data-theme=\"hell\"] body #sv68off{background:#fff4d6;color:#6b4a00;border-bottom-color:rgba(201,138,4,.35);}\n\n/* Knöpfe auch im hellen Modus flach (svhell.css setzt dort einen Verlauf) */\nhtml body:not(#_) .btn:not(.ghost){background:var(--brand)!important;background-image:none!important;box-shadow:none!important;}\nhtml body:not(#_) .trfab{display:none!important;}\n\n/* Kontrast (4,5:1): Stellen, die der Test im hellen und dunklen Modus findet */\n.tk-modus button.on{background:var(--brand)!important;color:#fff!important;box-shadow:none!important;}\nhtml[data-theme=\"hell\"] body .ht-tx small.ht-heute,html[data-theme=\"hell\"] body .mn-views .mn-add{color:#9a4508!important;}\nhtml[data-theme=\"hell\"] body .kal-tag{color:color-mix(in srgb,var(--c) 40%,#1b2235)!important;}\nhtml[data-theme=\"hell\"] body .rolechip{color:#1f45b5!important;}\n.kbhome small{color:var(--ink2)!important;}\n.kbhome.kbinv{background:var(--surface2)!important;border-color:var(--line)!important;box-shadow:none!important;}\n/* Hell: Status-Knöpfe in der Firmenakte behalten ihre Vereinsfarben (die automatische Übersetzung machte sie weiß auf weiß) */\nhtml[data-theme=\"hell\"] body .spo-akte .spo-stbar button.on{background:#1d2760!important;color:#fff!important;}\nhtml[data-theme=\"hell\"] body .spo-akte .spo-stbar button.on.s-partner{background:#e8741f!important;color:#1c1c22!important;}\n\n/* Tipp-Ziele am Touchscreen mindestens 44 x 44 (Apple) */\n@media (pointer:coarse){ .iconbtn{min-width:44px!important;min-height:44px!important;} }\n/* Kontrast hell und dunkel: Akzent als Schrift dunkler, aktive Umschalter mit Vereinsblau statt Hellblau */\nhtml[data-theme=\"hell\"] body{--accent:#a34a0c;--orange:#a34a0c;}\n.hub-in .mn31-sw button.act,.hf-filter button.on{background:var(--brand)!important;border-color:var(--brand)!important;color:#fff!important;}\n.hf-filter button.on i{color:#fff!important;}\nhtml[data-theme=\"hell\"] body .svt-chips button.on{background:var(--brand)!important;color:#fff!important;border-color:var(--brand)!important;}\nhtml[data-theme=\"hell\"] body .pbcard .what{color:var(--accent)!important;}\n.hf-filter button:not(.on) i{color:var(--ink2)!important;}\nhtml[data-theme=\"hell\"] .imp-okt{color:#15803d}\n\n/* 0.99.77 · Zahl an einem Reiter der unteren Leiste (z. B. Hinweise der Mannschaft).\n   Sportliche Leitung, 17.11.2026: „Leiste unten rutscht oft ins Bild.“ Die Zahl hatte in der Leiste keinen eigenen Stil und stand\n   als dritte Zeile unter dem Namen des Reiters. Sobald es etwas zu zählen gab, wurde die ganze Leiste höher und schob sich ins Bild.\n   Jetzt sitzt sie als Marke an der Ecke des Symbols und nimmt keinen Platz ein. */\n.tabbar .ti,.tabbar .tmore{position:relative;}\n.tabbar .ti .cnt,.tabbar .tmore .cnt{position:absolute;top:3px;left:calc(50% + 5px);min-width:17px;height:17px;padding:0 5px;border-radius:99px;box-sizing:border-box;\n  background:var(--cnt-rot,#e5484d);color:var(--cnt-hell,#fff);font:800 10px/17px var(--font,system-ui);letter-spacing:0;text-align:center;white-space:nowrap;pointer-events:none;}\n"; document.head.appendChild(s); }catch(e){} })();
